const uid=(prefix='id')=>`${prefix}_${(crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2)+Date.now().toString(36)).replaceAll('-','')}`;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const round=(x,n=1)=>Math.round(x*10**n)/10**n;
const median=a=>{if(!a.length)return 0;const s=[...a].sort((x,y)=>x-y),m=Math.floor(s.length/2);return s.length%2?s[m]:(s[m-1]+s[m])/2};
const mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[c]));
function localDate(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function parseLocalDate(s){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)}
function formatDuration(ms){if(!ms)return '—';const min=Math.round(ms/60000);return min<60?`${min} min`:`${Math.floor(min/60)}h ${min%60}m`}
function slug(s){return String(s).toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')}
function download(name,text,type='application/json'){const blob=text instanceof Blob?text:new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function e1rm(w,r){return w&&r?w*(1+r/30):0}
function roundIncrement(x,inc){if(!x)return inc;return Math.max(inc,Math.round(x/inc)*inc)}

