function getDay(id){return DAYS[id]||DAYS.pull1}
function slotConfig(slotId){for(const [dayId,d] of Object.entries(DAYS)){const s=d.slots.find(x=>x.id===slotId);if(s)return {...s,dayId}}return null}
function exercise(id){return EXERCISES[id]||{name:id,muscle:'Other',type:'isolation',increment:5,rest:90,e1rm:false,alts:[]}}
function targetRepBand(slot,week){const [lo,hi]=slot.range,p=WEEK_PLAN[week],span=hi-lo;if(p.repBias==='low')return[lo,Math.max(lo,Math.round(lo+span*.35))];if(p.repBias==='middle')return[Math.round(lo+span*.25),Math.round(lo+span*.65)];if(p.repBias==='upper')return[Math.round(lo+span*.55),hi];if(p.repBias==='load')return[lo,Math.round(lo+span*.5)];return[lo,hi]}

/* ---------- IndexedDB + migration ---------- */
const DB_NAME='brandonFitnessV4',DB_VERSION=1,STATE_KEY='state';
let db=null,state=null,saveTimer=null,pendingWorkoutResponse='same',calendarCursor=new Date(),sandboxDraft=null,subContext=null,restInterval=null;
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('app'))d.createObjectStore('app');if(!d.objectStoreNames.contains('backups'))d.createObjectStore('backups',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function idbGet(store,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),r=tx.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function idbPut(store,val,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite'),os=tx.objectStore(store),r=key===undefined?os.put(val):os.put(val,key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function idbDelete(store,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite'),r=tx.objectStore(store).delete(key);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
function idbAll(store){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),r=tx.objectStore(store).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function defaultState(){const mesoId=uid('meso'),gymId=uid('gym');return{
 version:4,createdAt:now(),updatedAt:now(),currentMesocycleId:mesoId,
 mesocycles:[{id:mesoId,name:'Mesocycle 1',startDate:localDate(),endDate:null,status:'active',createdAt:now()}],
 currentDayId:'pull1',currentWeek:1,workouts:[],checkins:[],activeSession:null,
 settings:{therapyDayIds:['pull1','legs'],defaultGymId:gymId,defaultTemplateId:'normal',autoBackupEnabled:true,lastAutoBackupAt:0},
 gyms:[{id:gymId,name:'Default Gym',createdAt:now()}],exerciseSetupNotes:{},programOverrides:{},therapyLegacy:[],migration:{from:null,at:null}
}}
function normalizeV4(s){const d=defaultState();s={...d,...s};s.version=4;s.mesocycles=s.mesocycles||d.mesocycles;s.workouts=s.workouts||[];s.checkins=s.checkins||[];s.settings={...d.settings,...(s.settings||{})};s.gyms=s.gyms?.length?s.gyms:d.gyms;s.exerciseSetupNotes=s.exerciseSetupNotes||{};s.programOverrides=s.programOverrides||{};return s}
function deterministicMesoId(name){return `meso_migrated_${slug(name||'legacy')}`}
function migrateV3(old){const base=defaultState(),names=new Set();(old.workouts||[]).forEach(w=>names.add(w.mesocycle||'Legacy'));(old.mesocycle?.archives||[]).forEach(a=>names.add(a.name));names.add(old.mesocycle?.name||'Mesocycle 1');const mesocycles=[...names].map(name=>({id:deterministicMesoId(name),name,startDate:name===old.mesocycle?.name?(old.mesocycle.startDate||''):((old.mesocycle?.archives||[]).find(a=>a.name===name)?.startDate||''),endDate:(old.mesocycle?.archives||[]).find(a=>a.name===name)?.endDate||null,status:name===old.mesocycle?.name?'active':'completed',createdAt:now()}));
 const gymId=base.settings.defaultGymId;
 const workouts=(old.workouts||[]).map(w=>{const dayId=OLD_DAY_MAP[w.day]||'pull1';const day=getDay(dayId);return{id:uid('session'),date:w.timestamp?localDate(new Date(w.timestamp)):(w.date||localDate()),timestamp:w.timestamp||new Date(`${w.date}T12:00:00`).getTime(),startTime:w.timestamp||null,endTime:w.timestamp||null,durationMs:null,dayId,week:+w.week||1,mesocycleId:deterministicMesoId(w.mesocycle||'Legacy'),gymId,templateId:'normal',sessionNotes:'Migrated from v3',symptomResponse:w.symptomResponse||null,aggravatorExerciseId:(w.aggravator&&w.aggravator!=='Not sure')?(NAME_TO_EXERCISE[String(w.aggravator).toLowerCase()]||null):null,exercises:(w.exercises||[]).map(oldEx=>{const exId=NAME_TO_EXERCISE[String(oldEx.name).toLowerCase()]||`legacy_${slug(oldEx.name)}`;const slot=day.slots.find(s=>s.exerciseId===exId)||{id:`${dayId}_legacy_${slug(oldEx.name)}`};return{slotId:slot.id,exerciseId:exId,substituteOf:null,notes:oldEx.notes||'',setupNotes:'',skipped:false,skipReason:null,plannedSets:(oldEx.sets||[]).length,sets:(oldEx.sets||[]).filter(x=>x.weight!=null&&x.reps!=null).map(x=>({id:uid('set'),type:'working',weight:+x.weight,reps:+x.reps,rir:x.rir==null?null:+x.rir,completedAt:null,restBeforeSec:null}))}}),therapy:null,prs:[],updatedAt:now()}});
 const checkins=(old.checkins||[]).map(c=>({id:uid('checkin'),date:c.timestamp?localDate(new Date(c.timestamp)):(c.date||localDate()),timestamp:c.timestamp||now(),bodyweight:c.bodyweight??null,sleep:c.sleep??null,backPain:c.backPain??null,sciatica:c.sciatica??null}));
 const activeName=old.mesocycle?.name||'Mesocycle 1';
 return normalizeV4({...base,currentMesocycleId:deterministicMesoId(activeName),mesocycles,currentDayId:OLD_DAY_MAP[old.currentDay]||'pull1',currentWeek:+old.currentWeek||1,workouts,checkins,settings:{...base.settings,therapyDayIds:(old.settings?.therapyDays||['Pull 1','Legs']).map(x=>OLD_DAY_MAP[x]).filter(Boolean)},therapyLegacy:old.therapyLogs||[],migration:{from:'v3',at:now()}})
}
async function loadState(){let s=await idbGet('app',STATE_KEY);if(s)return normalizeV4(s);for(const key of ['brandonFitnessV3','brandonFitnessV2','brandonFitnessV1']){try{const raw=localStorage.getItem(key);if(raw){s=migrateV3(JSON.parse(raw));s.migration.from=key;await idbPut('app',s,STATE_KEY);return s}}catch(e){console.warn('Migration skipped',key,e)}}s=defaultState();await idbPut('app',s,STATE_KEY);return s}
async function persist({critical=false,reason='autosave'}={}){if(!state)return;state.updatedAt=now();$('saveBadge').textContent='Saving…';$('saveBadge').className='status-pill saving';await idbPut('app',state,STATE_KEY);$('saveBadge').textContent='Saved';$('saveBadge').className='status-pill saved';if(critical)await maybeAutoBackup(reason)}
function schedulePersist(){clearTimeout(saveTimer);$('saveBadge').textContent='Saving…';$('saveBadge').className='status-pill saving';saveTimer=setTimeout(()=>persist(),250)}
function currentMeso(){return state.mesocycles.find(m=>m.id===state.currentMesocycleId)||state.mesocycles[0]}
function overrideFor(slotId){return state.programOverrides?.[state.currentMesocycleId]?.[slotId]||null}
function effectiveSlot(slot){const o=overrideFor(slot.id);return {...slot,baseSets:o?.baseSets??slot.baseSets,exerciseId:o?.exerciseId||slot.exerciseId}}

