function openDayDialog(){$('dayChoices').innerHTML=DAY_ORDER.map(id=>`<button data-day="${id}">${esc(getDay(id).name)}</button>`).join('');document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{state.currentDayId=b.dataset.day;schedulePersist();$('dayDialog').close();renderAllToday()});$('dayDialog').showModal()}
function renderTemplateDialog(){$('templateChoices').innerHTML=Object.entries(TEMPLATES).map(([id,t])=>`<button data-template="${id}"><strong>${esc(t.name)}</strong><div class="tiny">${esc(t.description)}</div></button>`).join('');document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{const id=b.dataset.template;if(state.activeSession&&sessionHasCompletedSets())return alert('Template cannot change after working sets are completed.');state.settings.defaultTemplateId=id;if(state.activeSession){state.activeSession=null;createActiveSession()}schedulePersist();$('templateDialog').close();renderAllToday()});$('templateDialog').showModal()}

