$('saveCheckin').onclick=async()=>{const item={id:uid('checkin'),date:localDate(),timestamp:now(),bodyweight:$('bw').value?+$('bw').value:null,sleep:$('sleep').value?+$('sleep').value:null,backPain:$('back').value!==''?+$('back').value:null,sciatica:$('sciatica').value!==''?+$('sciatica').value:null};state.checkins=state.checkins.filter(x=>x.date!==item.date);state.checkins.push(item);await persist();renderAllToday();alert('Check-in saved. Your active workout, if any, stayed intact.')};

