$('exerciseSelect').onchange=renderExerciseAnalytics;

/* ---------- Program sandbox + mesocycle planner ---------- */
function renderProgram(){const p=WEEK_PLAN[state.currentWeek];$('weekGuide').innerHTML=`<h3>Week ${state.currentWeek}: ${esc(p.phase)}</h3><p><strong>${esc(p.rir)}</strong></p><p class="muted">${esc(p.note)}</p>`;$('programList').innerHTML=DAY_ORDER.map(dayId=>{const d=getDay(dayId);return`<div class="card"><h3>${esc(d.name)}</h3>${d.slots.map(raw=>{const s=effectiveSlot(raw),c=coachTarget(s);return`<div class="programrow"><span>${esc(exercise(s.exerciseId).name)}<div class="tiny">${esc(c.action)} · ${esc(c.trend.kind)}</div></span><strong>${plannedSets(s)} × ${targetRepBand(s,state.currentWeek)[0]}–${targetRepBand(s,state.currentWeek)[1]}</strong></div>`}).join('')}</div>`}).join('');renderSandbox()}
function makeSandboxDraft(){const out={};for(const d of Object.values(DAYS))for(const raw of d.slots){const s=effectiveSlot(raw);out[s.id]={baseSets:s.baseSets,exerciseId:s.exerciseId}}return out}
function renderSandbox(){
  if(!sandboxDraft)sandboxDraft=makeSandboxDraft();
  $('sandboxList').innerHTML=DAY_ORDER.map(dayId=>{
    const d=getDay(dayId);
    const rows=d.slots.map(raw=>{
      const x=sandboxDraft[raw.id]||{baseSets:raw.baseSets,exerciseId:raw.exerciseId};
      const choices=[raw.exerciseId,...(exercise(raw.exerciseId).alts||[])].filter((id,i,a)=>a.indexOf(id)===i);
      return `<div class="sandbox-row"><div><strong>${esc(exercise(x.exerciseId).name)}</strong><div class="muted">${esc(exercise(x.exerciseId).muscle)} · base sets</div><select data-sandbox-exercise="${raw.id}">${choices.map(id=>`<option value="${id}" ${id===x.exerciseId?'selected':''}>${esc(exercise(id).name)}</option>`).join('')}</select></div><div class="sandbox-stepper"><button data-sandbox="${raw.id}" data-delta="-1">−</button><span class="sandbox-count">${x.baseSets}</span><button data-sandbox="${raw.id}" data-delta="1">+</button></div></div>`;
    }).join('');
    return `<h4>${esc(d.name)}</h4>${rows}`;
  }).join('');
  document.querySelectorAll('[data-sandbox]').forEach(b=>b.onclick=()=>{
    const x=sandboxDraft[b.dataset.sandbox];
    x.baseSets=clamp(x.baseSets+(+b.dataset.delta),1,6);
    renderSandbox();
  });
  document.querySelectorAll('[data-sandbox-exercise]').forEach(sel=>sel.onchange=()=>{
    const x=sandboxDraft[sel.dataset.sandboxExercise];
    x.exerciseId=sel.value;
    renderSandbox();
  });
  const totals={};
  for(const x of Object.values(sandboxDraft)){
    const m=exercise(x.exerciseId).muscle;
    totals[m]=(totals[m]||0)+x.baseSets;
  }
  $('sandboxVolume').innerHTML=`<p class="muted">Preview direct base sets across one full five-day rotation:</p>${Object.entries(totals).map(([m,n])=>`<span class="volume-pill">${esc(m)}: ${n}</span>`).join('')}`;
}
$('resetSandbox').onclick=()=>{sandboxDraft={};for(const d of Object.values(DAYS))for(const raw of d.slots)sandboxDraft[raw.id]={baseSets:raw.baseSets,exerciseId:raw.exerciseId};renderSandbox()};
$('saveSandbox').onclick=async()=>{state.programOverrides[state.currentMesocycleId]=clone(sandboxDraft);await persist({critical:true,reason:'program_changed'});renderProgram();renderAllToday();alert('Sandbox changes saved for this mesocycle.')};
$('advanceWeek').onclick=async()=>{if(state.currentWeek>=8)return alert('Week 8 is the end of the planned cycle. Open the mesocycle planner instead.');if(state.activeSession)return alert('Finish the active workout before changing mesocycle week.');const fatigue=DAY_ORDER.flatMap(d=>getDay(d).slots).map(s=>classifyTrend(comparableSessions(s.id,effectiveSlot(s).exerciseId,{limit:3}),effectiveSlot(s)).kind).filter(x=>x==='fatigue'||x==='regression').length;if(fatigue>=3&&!confirm(`${fatigue} exercise slots currently show fatigue/regression signals. Advance anyway? The mesocycle planner may recommend an early deload.`))return;state.currentWeek++;await persist({critical:true,reason:'week_advanced'});renderProgram();renderAllToday()};
function mesoPlannerReport(){const priority=[];for(const dayId of DAY_ORDER)for(const raw of getDay(dayId).slots){const s=effectiveSlot(raw);if(!s.priority)continue;const rows=comparableSessions(s.id,s.exerciseId,{mesoId:state.currentMesocycleId,limit:3}),t=classifyTrend(rows,s),a=symptomAssociation(s.exerciseId,8);priority.push({name:`${getDay(dayId).name} · ${exercise(s.exerciseId).name}`,trend:t.kind,text:t.text,assoc:a})}const improving=priority.filter(x=>x.trend==='improving').length,fatigue=priority.filter(x=>['fatigue','regression'].includes(x.trend)).length,flags=priority.filter(x=>x.assoc.aggravator>=2),ws=mesoWorkouts(),worse=ws.filter(w=>w.symptomResponse==='worse').length,recs=[];if(fatigue>=3&&state.currentWeek<8)recs.push('Multiple priority slots show fatigue/regression. Consider starting the deload now instead of advancing another hard week.');if(fatigue>=3)recs.push('Start the next cycle conservatively and consider reducing one set from repeatedly regressing muscle groups rather than adding volume.');else if(improving>=3)recs.push('Most priority work is still progressing. Keep the same exercise skeleton next cycle and re-earn volume from Week 1.');else recs.push('Keep the exercise skeleton stable enough to preserve comparability; use Week 1 to resensitize before deciding where volume should rise.');if(flags.length)recs.push(`Review technique/ROM or substitutions for ${flags.map(x=>x.name.split(' · ')[1]).join(', ')} because they have repeated user-selected symptom-aggravator flags.`);if(worse>=3)recs.push('Because several sessions were marked worse for back/leg symptoms, do not automatically escalate lower-body volume next cycle.');return{priority,improving,fatigue,flags,worse,recs}}
function openMesoPlanner(){const r=mesoPlannerReport(),m=currentMeso(),metrics=mesoSummaryMetrics(m);$('mesoPlannerContent').innerHTML=`<div class="stats-grid"><div class="stat"><span>Workouts</span><strong>${metrics.workouts}</strong></div><div class="stat"><span>Improving priority slots</span><strong>${r.improving}</strong></div><div class="stat"><span>Fatigue/regression</span><strong>${r.fatigue}</strong></div><div class="stat"><span>Symptom flags</span><strong>${r.flags.length}</strong></div></div><h4>Priority-slot review</h4><table class="metric-table"><thead><tr><th>Slot</th><th>State</th></tr></thead><tbody>${r.priority.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.trend)}</td></tr>`).join('')}</tbody></table><h4>Coach recommendations</h4><ul>${r.recs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="tiny">Planner recommendations are rule-based summaries of your logged training and symptom associations; they are not medical conclusions.</p>`;$('mesoPlannerDialog').showModal()}
$('plannerDeload').onclick=async()=>{if(state.activeSession)return alert('Finish the active workout first.');if(state.currentWeek===8)return alert('You are already in the deload week.');if(!confirm('Move the current mesocycle directly to Week 8 deload?'))return;state.currentWeek=8;await persist({critical:true,reason:'early_deload'});$('mesoPlannerDialog').close();renderProgram();renderAllToday();alert('Week 8 deload started early based on your decision.')};
$('openMesoPlanner').onclick=openMesoPlanner;$('completeMeso').onclick=openMesoPlanner;$('closeMesoPlanner').onclick=()=>$('mesoPlannerDialog').close();$('plannerComplete').onclick=async()=>{if(state.activeSession)return alert('Finish the active workout first.');if(!confirm('Archive the current mesocycle and start the next one at Week 1?'))return;const old=currentMeso();old.status='completed';old.endDate=localDate();old.completedAt=now();const n=state.mesocycles.length+1,id=uid('meso'),newM={id,name:`Mesocycle ${n}`,startDate:localDate(),endDate:null,status:'active',createdAt:now()};state.mesocycles.push(newM);state.programOverrides[id]=clone(state.programOverrides[old.id]||{});state.currentMesocycleId=id;state.currentWeek=1;sandboxDraft=null;$('mesoPlannerDialog').close();await persist({critical:true,reason:'mesocycle_completed'});renderSettings();renderProgram();renderAllToday();renderProgress();alert('Mesocycle archived. The next cycle starts at Week 1 and keeps your program structure while resetting progression targets.')};

/* ---------- Settings, gyms, templates ---------- */
function renderSettings(){const m=currentMeso();$('mesoNameInput').value=m?.name||'Mesocycle';$('weekInput').value=state.currentWeek;$('mesoStartInput').value=m?.startDate||'';$('therapyPull1').checked=state.settings.therapyDayIds.includes('pull1');$('therapyLegs').checked=state.settings.therapyDayIds.includes('legs');$('therapyPull2').checked=state.settings.therapyDayIds.includes('pull2');$('autoBackupEnabled').checked=!!state.settings.autoBackupEnabled;$('gymList').innerHTML=state.gyms.map(g=>`<div class="programrow"><span><strong>${esc(g.name)}</strong>${g.id===state.settings.defaultGymId?'<div class="tiny">Default gym · setup notes are keyed here</div>':''}</span><div class="button-row">${g.id!==state.settings.defaultGymId?`<button data-default-gym="${g.id}">Make default</button>`:''}${state.gyms.length>1?`<button data-delete-gym="${g.id}">Delete</button>`:''}</div></div>`).join('');document.querySelectorAll('[data-default-gym]').forEach(b=>b.onclick=async()=>{state.settings.defaultGymId=b.dataset.defaultGym;await persist();renderSettings();renderAllToday()});document.querySelectorAll('[data-delete-gym]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this gym profile? Historical workouts keep the gym ID, but saved setup notes for it will no longer be shown.'))return;state.gyms=state.gyms.filter(g=>g.id!==b.dataset.deleteGym);await persist();renderSettings()});$('defaultTemplate').innerHTML=Object.entries(TEMPLATES).map(([id,t])=>`<option value="${id}">${esc(t.name)}</option>`).join('');$('defaultTemplate').value=state.settings.defaultTemplateId;$('templateInfo').textContent=TEMPLATES[state.settings.defaultTemplateId]?.description||'';renderBackupStatus()}
$('saveMeso').onclick=async()=>{const m=currentMeso();m.name=$('mesoNameInput').value.trim()||m.name;m.startDate=$('mesoStartInput').value;state.currentWeek=clamp(+$('weekInput').value||1,1,8);await persist({critical:true,reason:'mesocycle_settings'});renderSettings();renderProgram();renderAllToday()};
$('addGym').onclick=async()=>{const name=$('newGymName').value.trim();if(!name)return;const g={id:uid('gym'),name,createdAt:now()};state.gyms.push(g);$('newGymName').value='';await persist();renderSettings()};
$('defaultTemplate').onchange=async()=>{state.settings.defaultTemplateId=$('defaultTemplate').value;await persist();renderSettings();renderAllToday()};
$('saveTherapyDays').onclick=async()=>{state.settings.therapyDayIds=[];if($('therapyPull1').checked)state.settings.therapyDayIds.push('pull1');if($('therapyLegs').checked)state.settings.therapyDayIds.push('legs');if($('therapyPull2').checked)state.settings.therapyDayIds.push('pull2');await persist();renderAllToday();alert('Therapy schedule saved.')};
$('autoBackupEnabled').onchange=async()=>{state.settings.autoBackupEnabled=$('autoBackupEnabled').checked;await persist();renderBackupStatus()};

/* ---------- Encrypted backups + import/export ---------- */
function bytesToB64(bytes){let s='';bytes.forEach(b=>s+=String.fromCharCode(b));return btoa(s)}
function b64ToBytes(s){const raw=atob(s),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
async function deviceCryptoKey(){let raw=localStorage.getItem('brandonFitnessV4DeviceKey');if(!raw){const b=crypto.getRandomValues(new Uint8Array(32));raw=bytesToB64(b);localStorage.setItem('brandonFitnessV4DeviceKey',raw)}return crypto.subtle.importKey('raw',b64ToBytes(raw),'AES-GCM',false,['encrypt','decrypt'])}
async function encryptJsonWithKey(obj,key){const iv=crypto.getRandomValues(new Uint8Array(12)),data=new TextEncoder().encode(JSON.stringify(obj)),enc=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,data);return{iv:bytesToB64(iv),data:bytesToB64(new Uint8Array(enc))}}
async function decryptJsonWithKey(payload,key){const dec=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(payload.iv)},key,b64ToBytes(payload.data));return JSON.parse(new TextDecoder().decode(dec))}
async function maybeAutoBackup(reason='periodic',force=false){if(!state.settings.autoBackupEnabled&&!force)return;const interval=24*60*60*1000;if(!force&&now()-(state.settings.lastAutoBackupAt||0)<interval)return;try{const key=await deviceCryptoKey(),enc=await encryptJsonWithKey(state,key),rec={id:uid('backup'),timestamp:now(),date:localDate(),reason,format:'bf4-device-aes-gcm',...enc};await idbPut('backups',rec);state.settings.lastAutoBackupAt=rec.timestamp;await idbPut('app',state,STATE_KEY);const all=(await idbAll('backups')).sort((a,b)=>b.timestamp-a.timestamp);for(const x of all.slice(12))await idbDelete('backups',x.id);renderBackupStatus()}catch(e){console.warn('Auto backup failed',e)}}
async function renderBackupStatus(){if(!$('backupStatus'))return;try{const all=(await idbAll('backups')).sort((a,b)=>b.timestamp-a.timestamp),last=all[0];$('backupStatus').textContent=last?`${all.length} encrypted local snapshot${all.length===1?'':'s'} · latest ${new Date(last.timestamp).toLocaleString()} (${last.reason})`:'No encrypted local snapshots yet.'}catch(e){$('backupStatus').textContent='Backup status unavailable.'}}
async function passphraseKey(pass,salt,usage=['encrypt','decrypt']){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,usage)}
async function exportEncrypted(){const pass=prompt('Create a passphrase for this encrypted backup. You will need the exact passphrase to restore it.');if(!pass)return;if(pass.length<6)return alert('Use at least 6 characters.');const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await passphraseKey(pass,salt),plain=new TextEncoder().encode(JSON.stringify(state)),enc=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain),payload={format:'brandon-fitness-v4-encrypted',kdf:'PBKDF2-SHA256',iterations:180000,salt:bytesToB64(salt),iv:bytesToB64(iv),data:bytesToB64(new Uint8Array(enc))};download(`brandon-fitness-v4-encrypted-${localDate()}.bf4`,JSON.stringify(payload),'application/octet-stream')}
async function importPayload(file){const text=await file.text(),parsed=JSON.parse(text);if(parsed.format==='brandon-fitness-v4-encrypted'){const pass=prompt('Enter the backup passphrase.');if(!pass)throw new Error('No passphrase');const salt=b64ToBytes(parsed.salt),iv=b64ToBytes(parsed.iv),key=await passphraseKey(pass,salt),dec=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,b64ToBytes(parsed.data));return JSON.parse(new TextDecoder().decode(dec))}return parsed}
$('snapshotNow').onclick=async()=>{await maybeAutoBackup('manual_snapshot',true);alert('Encrypted local snapshot created.')};
$('restoreSnapshot').onclick=async()=>{const all=(await idbAll('backups')).sort((a,b)=>b.timestamp-a.timestamp),last=all[0];if(!last)return alert('No local snapshot exists yet.');if(!confirm(`Restore the latest snapshot from ${new Date(last.timestamp).toLocaleString()}? Current unsnapshotted changes will be replaced.`))return;try{const key=await deviceCryptoKey(),restored=await decryptJsonWithKey(last,key);state=normalizeV4(restored);await idbPut('app',state,STATE_KEY);renderEverything();alert('Latest local snapshot restored.')}catch(e){alert('Snapshot could not be decrypted on this device.')}};
$('exportBtn').onclick=()=>download(`brandon-fitness-v4-backup-${localDate()}.json`,JSON.stringify(state,null,2));$('exportEncryptedBtn').onclick=exportEncrypted;
$('exportCsvBtn').onclick=()=>{const rows=[['session_id','date','mesocycle_id','mesocycle','week','day','gym','exercise_slot_id','exercise_id','exercise','set_id','weight','reps','rir','rest_before_sec','symptom_response','suspected_aggravator','duration_min','sets_per_hour']];for(const w of state.workouts)for(const e of w.exercises||[])for(const s of validWorkingSets(e))rows.push([w.id,w.date,w.mesocycleId,state.mesocycles.find(m=>m.id===w.mesocycleId)?.name||'',w.week,getDay(w.dayId).name,state.gyms.find(g=>g.id===w.gymId)?.name||'',e.slotId,e.exerciseId,exercise(e.exerciseId).name,s.id,s.weight,s.reps,s.rir??'',s.restBeforeSec??'',w.symptomResponse??'',w.aggravatorExerciseId?exercise(w.aggravatorExerciseId).name:'',w.durationMs?round(w.durationMs/60000,1):'',w.efficiency?.setsPerHour?round(w.efficiency.setsPerHour,1):'']);const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');download(`brandon-fitness-v4-workouts-${localDate()}.csv`,csv,'text/csv')};
$('importFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{let imported=await importPayload(file);if(imported.version===3||(!imported.version&&imported.workouts))imported=migrateV3(imported);if(imported.version!==4)throw new Error('Unsupported version');if(!confirm('Import this backup and replace current v4 state? An automatic snapshot of the current state will be created first.'))return;await maybeAutoBackup('pre_import',true);state=normalizeV4(imported);await idbPut('app',state,STATE_KEY);renderEverything();alert('Backup imported.')}catch(err){console.error(err);alert('Could not read or decrypt that backup.')}finally{e.target.value=''}};
$('resetBtn').onclick=async()=>{if(!confirm('Erase all Brandon Fitness v4 data on this device, including workouts and active-session drafts?'))return;if(!confirm('Final confirmation: this cannot be undone unless you exported a backup. Local snapshots will be deleted too.'))return;state=defaultState();const all=await idbAll('backups');for(const b of all)await idbDelete('backups',b.id);await idbPut('app',state,STATE_KEY);renderEverything();alert('v4 local data erased.')};

/* ---------- Navigation + lifecycle ---------- */
function show(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));if(id==='history')renderHistory();if(id==='progress')renderProgress();if(id==='program')renderProgram();if(id==='settings')renderSettings();if(id==='today')renderAllToday()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));
function updateOnline(){const online=navigator.onLine;$('onlineBadge').textContent=online?'Online · local-first':'Offline · fully usable';$('onlineBadge').className=`status-pill ${online?'':'offline'}`}
window.addEventListener('online',updateOnline);window.addEventListener('offline',updateOnline);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state)persist()});window.addEventListener('pagehide',()=>{if(state)persist()});
function renderEverything(){sandboxDraft=null;renderAllToday();renderHistory();renderProgress();renderProgram();renderSettings();updateOnline()}
async function init(){try{db=await openDB();state=await loadState();renderEverything();if(state.migration?.from&&!state.migration.acknowledged){state.migration.acknowledged=true;await persist();setTimeout(()=>alert(`v4 migrated your ${state.migration.from} data into IndexedDB. The old localStorage copy was left untouched as a fallback.`),300)}await maybeAutoBackup('startup_periodic');if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js').catch(console.warn))}catch(e){console.error(e);document.querySelector('main').innerHTML=`<div class="card"><h2>Could not start v4</h2><p class="muted">${esc(e.message||e)}</p></div>`}}
init();
